          height,
          pose: app.persistence.poseOf(group),
        })),
      restore: (saved) => {
        this.restoreGeneration = this.clearGeneration;
        return this.restoreWorldPhotos(saved);
      },
    });
  }

  /** カメラの映像が取れていて、写真に現実の景色が入るか */
  get cameraReady(): boolean {
    const video = this.video;
